#!/bin/bash
# usage: plu.sh <word>  -> prints exactly pluralize(word) (via cardinalize(word, 4) => line 2)
/workspace/dataset/test12_executable --a "1,2,3,4" --b "$1" 2>&1 | sed -n 2p
---
#!/bin/bash
# usage: p.sh <word> [count]   -> prints the 5 result lines for a word with `count` items
w="$1"; n="${2:-4}"
a=""
for ((i=1;i<=n;i++)); do if [ -z "$a" ]; then a="i$i"; else a="$a,i$i"; fi; done
/workspace/dataset/test12_executable --a "$a" --b "$w" 2>&1
---
#!/bin/bash
# usage: batch.sh <file-with-one-word-per-line>  -> "word\tplural"
run(){ printf '%s\t%s\n' "$1" "$(/workspace/dataset/test12_executable --a "1,2,3,4" --b "$1" 2>&1 | sed -n 2p)"; }
export -f run
cat "$1" | xargs -d '\n' -I{} -P 32 bash -c 'run "$@"' _ {}
---
#!/bin/bash
# usage: batch2.sh <file>  -> word<TAB>plural<TAB>singular  (tabs/newlines in word not supported)
run(){ o=$(/workspace/dataset/test12_executable --a "1,2,3,4" --b "$1" 2>&1); p=$(sed -n 2p <<<"$o"); s=$(sed -n 4p <<<"$o"); printf '%s\t%s\t%s\n' "$1" "$p" "$s"; }
export -f run
xargs -d '\n' -I{} -P 32 bash -c 'run "$@"' _ {} < "$1"

