cat > /tmp/probe/check.awk <<'AWK'
BEGIN{FS="\t"}
{
  w=$1; p=$2;
  if (w !~ /^[a-z]+$/) next;   # only simple lowercase words
  n=length(w);
  last=substr(w,n,1); last2=(n>=2?substr(w,n-1,2):"");
  if (last2=="es") pred=w;
  else if (last=="y" && n>=2 && substr(w,n-1,1) !~ /[aeiou]/) pred=substr(w,1,n-1) "ies";
  else if (last=="s" || last2=="ch" || last2=="sh") pred=w "es";
  else pred=w "s";
  if (pred != p) printf "%s\t%s\t(pred %s)\n", w, p, pred;
}
AWK
sort -u /tmp/probe/data/counts-format.tsv | awk -f /tmp/probe/check.awk | sort
